from typing import List

def factorize(n: int) -> List[int]:
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n = n // d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """Parse a string of nested parentheses groups and return the maximum depth of nesting for each group."""
    groups = paren_string.split()
    result = []

    for group in groups:
        current_depth = 0
        max_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            else:
                current_depth -= 1
        result.append(max_depth)

    return result

