import math

def triangle_area(a, b, c):
    sorted_sides = sorted([a, b, c])
    if sorted_sides[0] + sorted_sides[1] <= sorted_sides[2]:
        return -1
    s = (sorted_sides[0] + sorted_sides[1] + sorted_sides[2]) / 2
    area = math.sqrt(s * (s - sorted_sides[0]) * (s - sorted_sides[1]) * (s - sorted_sides[2]))
    return round(area, 2)
