def max_bitonic_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    inc = [0] * n
    dec = [0] * n

    # Initialize inc array
    for i in range(n):
        inc[i] = arr[i]

    # Compute inc array
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Initialize dec array
    for i in range(n-1, -1, -1):
        dec[i] = arr[i]

    # Compute dec array
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Calculate the maximum bitonic sum
    max_sum = 0
    for i in range(n):
        current_sum = inc[i] + dec[i] - arr[i]
        if current_sum > max_sum:
            max_sum = current_sum

    return max_sum

