def count_Primes_nums(n):
    if n <= 1:
        return 0
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True
    count = 0
    for i in range(2, n):
        if is_prime(i):
            count += 1
    return count
