def is_decimal(s):
    if '.' not in s:
        return False
    parts = s.split('.')
    if len(parts) != 2:
        return False
    integer_part, decimal_part = parts
    if len(decimal_part) != 2:
        return False
    if not decimal_part.isdigit():
        return False
    if not integer_part:
        return False
    return True

# Test case
assert is_decimal('123.11') == True

def find_min_diff(arr, num):
    # Filter the array to include only elements >= num
    filtered = [x for x in arr if x >= num]

    # If there are fewer than two elements in the filtered list, return None
    if len(filtered) < 2:
        return None

    min_diff = float('inf')
    # Iterate through all pairs of elements in the filtered list
    for i in range(len(filtered)):
        for j in range(i + 1, len(filtered)):
            diff = filtered[j] - filtered[i]
            if diff < min_diff:
                min_diff = diff

    return min_diff

